      $PSStyle.Formatting.Warning = "$e[38;2;249;215;159m"
      $PSStyle.Formatting.Verbose = "$e[38;2;165;216;247m"
      $PSStyle.Formatting.Debug = "$e[38;2;138;144;155m"
